    end = min(interval1[1], interval2[1])
    if start > end:
        return "NO"
    intersection_length = end - start + 1
    if intersection_length <= 1:
        return "NO"
    for i in range(2, int(intersection_length**0.5) + 1):
        if intersection_length % i == 0:
            return "NO"
    return "YES"
